class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0
        for i in range(n):
            for j in range(i, n):
                rem = nums[:i] + nums[j+1:]
                if all(rem[t] < rem[t+1] for t in range(len(rem) - 1)):
                    ans += 1
        return ans

