class Solution {
public:
    int incremovableSubarrayCount(vector<int>& nums) {
        int n = nums.size(), ans = 0;
        for (int i = 0; i < n; i++)
            for (int j = i; j < n; j++) {
                vector<int> rem;
                for (int t = 0; t < n; t++)
                    if (t < i || t > j) rem.push_back(nums[t]);
                bool ok = true;
                for (int t = 0; t + 1 < (int)rem.size(); t++)
                    if (rem[t] >= rem[t+1]) { ok = false; break; }
                ans += ok;
            }
        return ans;
    }
};

