class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        n = len(nums)
        pre = [True] * (n + 1)
        for i in range(1, n):
            pre[i + 1] = pre[i] and nums[i - 1] < nums[i]
        suf = [True] * (n + 1)
        for j in range(n - 2, -1, -1):
            suf[j] = suf[j + 1] and nums[j] < nums[j + 1]
        ans = 0
        for i in range(n):
            for j in range(i, n):
                if pre[i] and suf[j + 1] and (i == 0 or j == n - 1 or nums[i - 1] < nums[j + 1]):
                    ans += 1
        return ans

