class Solution {
public:
    int incremovableSubarrayCount(vector<int>& nums) {
        int n = nums.size(), ans = 0;
        vector<bool> pre(n + 1, true), suf(n + 1, true);
        for (int i = 1; i < n; i++) pre[i + 1] = pre[i] && nums[i-1] < nums[i];
        for (int j = n - 2; j >= 0; j--) suf[j] = suf[j+1] && nums[j] < nums[j+1];
        for (int i = 0; i < n; i++)
            for (int j = i; j < n; j++)
                if (pre[i] && suf[j+1] && (i == 0 || j == n-1 || nums[i-1] < nums[j+1]))
                    ans++;
        return ans;
    }
};

